\set ON_ERROR_STOP on
BEGIN READ ONLY;
SET LOCAL statement_timeout = '240s';
\copy (WITH s AS (SELECT id, company_id, chat_id, channel, started_at, had_handoff, agent_messages, status FROM conversation_sessions WHERE started_at >= '@FROM@'::timestamptz AND started_at < '@TO@'::timestamptz), m AS (SELECT s.id sid, x.* FROM s CROSS JOIN LATERAL (SELECT mm.timestamp ts, mm.is_from_customer cust, mm.is_from_ai ai, coalesce(mm.content,'') content, mm.media_type FROM messages mm WHERE mm.conversation_session_id = s.id ORDER BY mm.timestamp LIMIT 12) x), fr AS (SELECT DISTINCT ON (sid) sid, ai FROM m WHERE NOT cust ORDER BY sid, ts), firsthuman AS (SELECT sid, min(ts) hts FROM m WHERE NOT cust AND NOT ai GROUP BY sid), w AS (SELECT m.*, row_number() OVER (PARTITION BY m.sid ORDER BY m.ts) rn, lag(m.ts) OVER (PARTITION BY m.sid, m.cust ORDER BY m.ts) prev_same, lower(regexp_replace(m.content, '\s+', ' ', 'g')) norm FROM m LEFT JOIN firsthuman f ON f.sid = m.sid WHERE f.hts IS NULL OR m.ts < f.hts), w4 AS (SELECT * FROM w WHERE rn <= 4), rep AS (SELECT a.sid, count(*) n FROM w4 a WHERE a.cust AND length(a.norm) > 0 AND EXISTS (SELECT 1 FROM w4 b WHERE b.sid = a.sid AND b.cust AND b.rn < a.rn AND b.norm = a.norm) GROUP BY a.sid), agg AS (SELECT sid, count(*) n_window, count(*) FILTER (WHERE cust) w_customer_msgs, count(*) FILTER (WHERE ai) w_ai_msgs, avg(length(content)) FILTER (WHERE cust) cust_chars_mean, max(length(content)) FILTER (WHERE cust) cust_chars_max, sum(length(content) - length(replace(content, '?', ''))) FILTER (WHERE cust) cust_question_marks, count(*) FILTER (WHERE cust AND media_type ILIKE 'image%') media_image, count(*) FILTER (WHERE cust AND (media_type ILIKE 'audio%' OR media_type ILIKE 'voice%')) media_audio, count(*) FILTER (WHERE cust AND (media_type ILIKE 'document%' OR media_type ILIKE 'application%')) media_document, count(*) FILTER (WHERE cust AND media_type IS NOT NULL AND media_type NOT ILIKE 'image%' AND media_type NOT ILIKE 'audio%' AND media_type NOT ILIKE 'voice%' AND media_type NOT ILIKE 'document%' AND media_type NOT ILIKE 'application%' AND media_type <> 'text') media_other, extract(epoch FROM (min(ts) FILTER (WHERE ai) - min(ts) FILTER (WHERE cust))) first_ai_reply_s, avg(extract(epoch FROM (ts - prev_same))) FILTER (WHERE cust AND prev_same IS NOT NULL) cust_gap_mean_s, avg(length(content)) FILTER (WHERE ai) ai_chars_mean, bool_or(ai AND norm ~ '(no tengo|no cuento con|no dispongo|no puedo ayudarte|no tengo acceso|no encontr)') ai_no_info, bool_or(cust AND norm ~ '(asesor|humano|una persona|agente real|hablar con alguien)') cust_asks_human, bool_or(cust AND norm ~ '(queja|reclamo|pesimo|pésimo|terrible|molest|estafa|nadie responde)') cust_negative_words FROM w4 GROUP BY sid) SELECT s.company_id, s.chat_id, s.started_at, s.channel, extract(hour FROM s.started_at AT TIME ZONE 'America/Bogota')::int hour_local, extract(isodow FROM s.started_at AT TIME ZONE 'America/Bogota')::int dow, a.w_customer_msgs, a.w_ai_msgs, round(a.cust_chars_mean::numeric, 1) cust_chars_mean, a.cust_chars_max, a.cust_question_marks, coalesce(r.n, 0) cust_repeats, a.media_image, a.media_audio, a.media_document, a.media_other, round(a.first_ai_reply_s::numeric, 1) first_ai_reply_s, round(a.cust_gap_mean_s::numeric, 1) cust_gap_mean_s, round(a.ai_chars_mean::numeric, 1) ai_chars_mean, coalesce(a.ai_no_info, false)::int ai_no_info, coalesce(a.cust_asks_human, false)::int cust_asks_human, coalesce(a.cust_negative_words, false)::int cust_negative_words, (s.had_handoff OR s.status IN ('transferred', 'abandoned') OR EXISTS (SELECT 1 FROM messages hm WHERE hm.conversation_session_id = s.id AND NOT hm.is_from_customer AND NOT hm.is_from_ai))::int needed_human FROM s JOIN fr ON fr.sid = s.id AND fr.ai JOIN agg a ON a.sid = s.id LEFT JOIN rep r ON r.sid = s.id WHERE a.n_window = 4 AND a.w_customer_msgs >= 1) TO STDOUT WITH CSV HEADER
COMMIT;
